func users(db *sql.DB, minAge int) ([]User, error) {
    rows, err := db.Query("SELECT id, name FROM users WHERE age > " + strconv.Itoa(minAge))
    if err != nil {
        return nil, err
    }
    var out []User
    for rows.Next() {
        var u User
        rows.Scan(&u.ID, &u.Name)
        out = append(out, u)
    }
    return out, nil
}

func transfer(ctx context.Context, db *sql.DB, from, to int, amt int) error {
    tx, err := db.BeginTx(ctx, nil)
    if err != nil {
        return err
    }
    if _, err := tx.ExecContext(ctx, "UPDATE acc SET bal = bal - $1 WHERE id = $2", amt, from); err != nil {
        return err
    }
    if _, err := tx.ExecContext(ctx, "UPDATE acc SET bal = bal + $1 WHERE id = $2", amt, to); err != nil {
        return err
    }
    return tx.Commit()
}
